macro_rules! deps {
    () => {
        AutodiffStage!();
        SanitizerOptions!();
        LlvmCodegenBackend!();
        OptStage!();
        LlvmSelfProfiler!();
        LlvmError!();
        ModuleLlvm!();
    };
}

